// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.SourceRun.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//		).
//		Exec(ctx)
func (u *SourceRunUpsertBulk) UpdateNewValues() *SourceRunUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.RunKey(); exists {
				s.SetIgnore(sourcerun.FieldRunKey)
			}
			if _, exists := b.mutation.SourceKey(); exists {
				s.SetIgnore(sourcerun.FieldSourceKey)
			}
			if _, exists := b.mutation.SourceInstance(); exists {
				s.SetIgnore(sourcerun.FieldSourceInstance)
			}
			if _, exists := b.mutation.ScopeKind(); exists {
				s.SetIgnore(sourcerun.FieldScopeKind)
			}
			if _, exists := b.mutation.ScopeKey(); exists {
				s.SetIgnore(sourcerun.FieldScopeKey)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(sourcerun.FieldCreatedAt)
			}
		}
	}))
	return u
}

